package com.nexushr.service; import com.nexushr.entity.*; import com.nexushr.repository.*; import org.springframework.stereotype.Service; import java.time.*; import java.util.*;
@Service public class DashboardService {final EmployeeRepository e;final LeaveRequestRepository l;final AttendanceRepository a;final PayrollRepository p;public DashboardService(EmployeeRepository e,LeaveRequestRepository l,AttendanceRepository a,PayrollRepository p){this.e=e;this.l=l;this.a=a;this.p=p;} public Map<String,Object> dashboard(){var m=new LinkedHashMap<String,Object>();m.put("totalEmployees",e.count());m.put("activeEmployees",e.count());m.put("onboardingPending",e.countByOnboardingComplete(false));m.put("pendingLeaves",l.countByStatus(LeaveStatus.PENDING));m.put("todayPresent",a.countByWorkDateAndStatus(LocalDate.now(),AttendanceStatus.PRESENT));m.put("todayAbsent",a.countByWorkDateAndStatus(LocalDate.now(),AttendanceStatus.ABSENT));m.put("payrollMonth",YearMonth.now().toString());m.put("payrollProcessed",p.findByPayrollMonthOrderByEmployeeEmployeeCode(YearMonth.now().toString()).size());return m;} public Map<String,Object> insights(){var m=new LinkedHashMap<String,Object>();long total=e.count();long pending=e.countByOnboardingComplete(false);m.put("headcount",total);m.put("onboardingPending",pending);m.put("onboardingCompletionRate",total==0?100.0:Math.round((total-pending)*10000.0/total)/100.0);m.put("pendingLeaveRequests",l.countByStatus(LeaveStatus.PENDING));m.put("generatedAt",LocalDateTime.now());m.put("insights",List.of("Review pending leave requests","Follow up on incomplete onboarding","Monitor attendance exceptions"));return m;}}
